
/**
 * Purpose: Main React application, role navigation, and student data loading.
 *
 * Original application structure: Existing project code.
 * Modification: Load demo students from FastAPI while preserving
 * the existing teacher and student interfaces.
 *
 * Directed and reviewed by: Edenna Chen
 * Modifications generated by: ChatGPT (OpenAI), GPT-6, 2026-11-05
 * Human edits: Existing project code preserved.
 * External sources: None
 *
 * Notes:
 * - Loads the four seeded demo students from SQLite through FastAPI.
 * - Keeps existing frontend mock data until dashboard integration.
 * - Does not modify database records.
 * - The student portal still uses the existing demo student.
 */

import { useEffect, useState } from 'react';

import Sidebar from './components/Sidebar';

import Home from './pages/student/Home';
import Calibration from './pages/student/Calibration';
import Learn from './pages/student/Learn';
import Profile from './pages/student/Profile';
import Avatar from './pages/student/Avatar';

import Dashboard from './pages/teacher/Dashboard';
import Students from './pages/teacher/Students';
import Assignments from './pages/teacher/Assignments';
import Analytics from './pages/teacher/Analytics';
import Settings from './pages/teacher/Settings';

import { useLocalState } from './hooks/useLocalState';

import { getDemoStudents } from './api/students';
import type { ApiStudent } from './api/students';

import { initialStudents } from './data/mock';
import type { Role, Student } from './types';

export default function App() {
  // Existing application navigation.
  const [role, setRole] = useState<Role | null>(null);
  const [page, setPage] = useState('Home');

  // Existing frontend demo data.
  const [students, setStudents] = useLocalState<Student[]>(
    'adaptive-demo-students',
    initialStudents
  );

  // New: Students loaded from the FastAPI backend.
  const [demoStudents, setDemoStudents] = useState<ApiStudent[]>([]);
  const [studentsLoading, setStudentsLoading] = useState(true);
  const [studentsError, setStudentsError] = useState<string | null>(null);

  const [selectedStudentId, setSelectedStudentId] =
  useState<string | null>(null);

  useEffect(() => {
    let active = true;

    getDemoStudents()
      .then(data => {
        if (active) {
          setDemoStudents(data);
        }
      })
      .catch(error => {
        if (active) {
          setStudentsError(
            error instanceof Error
              ? error.message
              : 'Unable to load students'
          );
        }
      })
      .finally(() => {
        if (active) {
          setStudentsLoading(false);
        }
      });

    return () => {
      active = false;
    };
  }, []);

  // Temporary: Make backend loading visible during integration.
  // This prevents the new state variables from being unused.
  const backendStatus = studentsLoading
    ? 'Loading students...'
    : studentsError
      ? 'Student API unavailable'
      : `${demoStudents.length} demo students loaded`;

  // Existing student portal uses the first mock student.
  const student = students[0];

  const updateStudent = (
    id: string,
    changes: Partial<Student>
  ) => {
    setStudents(prev =>
      prev.map(s =>
        s.id === id ? { ...s, ...changes } : s
      )
    );
  };

  const chooseRole = (next: Role) => {
    setRole(next);
    setPage(next === 'student' ? 'Home' : 'Dashboard');
  };

  // Role selection screen.
  if (!role) {
    return (
      <div className="role-entry">
        <div className="role-entry-card">
          <div className="logo-mark">✦</div>

          <p className="eyebrow">ADAPTIVE CLASSROOM</p>

          <h1>How would you like to explore?</h1>

          <p className="lead">
            Choose a view to explore the classroom prototype.
            No login needed.
          </p>

          <div className="role-cards">
            <button
              className="role-card"
              onClick={() => chooseRole('student')}
            >
              <span>🎒</span>
              <strong>Student</strong>
              <small>
                Lessons, calibration, profile and avatar
              </small>
            </button>

            <button
              className="role-card"
              onClick={() => chooseRole('teacher')}
            >
              <span>📋</span>
              <strong>Teacher</strong>
              <small>
                Class overview, students and assignments
              </small>
            </button>
          </div>

          <p className="muted small">
            Demo only — switch roles at any time.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="app-shell">
      <Sidebar
        role={role}
        page={page}
        onNavigate={setPage}
        onSignOut={() => setRole(null)}
      />

      <main className="main-content">
        <header className="topbar">
          <span>
            {role === 'student'
              ? 'Student portal'
              : 'Teacher portal'}
          </span>

          <span className="topbar-account">
            {role === 'student' ? student.avatar : '📋'}
            {' '}Demo view
          </span>
        </header>

        {role === 'student' ? (
          <>
            {page === 'Home' && (
              <Home
                student={student}
                onNavigate={setPage}
              />
            )}

            {page === 'Calibration' && (
              <Calibration
                student={student}
                onUpdate={changes =>
                  updateStudent(student.id, changes)
                }
              />
            )}

            {page === 'Learn' && (
              <Learn
                student={student}
                onComplete={() =>
                  updateStudent(student.id, {
                    mastery: Math.min(
                      100,
                      student.mastery + 10
                    ),
                    completed: student.completed + 1,
                  })
                }
              />
            )}

            {page === 'Profile' && (
              <Profile
                student={student}
                onNavigate={setPage}
              />
            )}

            {page === 'Avatar' && (
              <Avatar
                student={student}
                onUpdate={changes =>
                  updateStudent(student.id, changes)
                }
              />
            )}
          </>
        ) : (
          <>
            {/* Temporary backend connection indicator. */}
            <p className="muted small" role="status">
              {backendStatus}
            </p>

            
            {page === 'Dashboard' && (
            <Dashboard
                students={demoStudents}
                loading={studentsLoading}
                error={studentsError}
                onSelectStudent={studentId => {
                setSelectedStudentId(studentId);
                setPage('Students');
                }}
            />
            )}


            
            {page === 'Students' && (
            <Students
                students={demoStudents}
                selectedStudentId={selectedStudentId}
                onCreateLesson={studentId => {
                setSelectedStudentId(studentId);
                setPage('Assignments');
                }}
            />
            )}


            {page === 'Assignments' && (
            <Assignments
                students={demoStudents}
                selectedStudentId={selectedStudentId}
            />
            )}

            {page === 'Analytics' && (
              <Analytics students={students} />
            )}

            {page === 'Settings' && (
              <Settings />
            )}
          </>
        )}
      </main>
    </div>
  );
}
